(function(){'use strict';var sheet=document.getElementById('mw-move-sheet');if(!sheet)return;var dateInput=document.getElementById('mw-move-date');var confirmBtn=document.getElementById('mw-move-confirm');var subEl=document.getElementById('mw-move-sub');var warnEl=document.getElementById('mw-move-warning');var chips=sheet.querySelectorAll('.mw-move-chip');var current=null;var force=!1;var busy=!1;function toast(msg,type){if(window.mwToast){window.mwToast(msg,type||'success')}else{alert(msg)}}
function toISO(d){return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2)}
function parseISO(iso){var p=(iso||'').split('-');return p.length===3?new Date(+p[0],+p[1]-1,+p[2]):new Date()}
function prettyDate(iso){return parseISO(iso).toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}
function setDate(iso){dateInput.value=iso;dateInput.dispatchEvent(new Event('change',{bubbles:!0}))}
function resetWarning(){force=!1;warnEl.hidden=!0;warnEl.textContent='';confirmBtn.textContent='Move'}
function refreshConfirm(){var ok=!!dateInput.value&&current&&dateInput.value!==current.fromDate;confirmBtn.disabled=!ok||busy;chips.forEach(function(chip){var d=parseISO(current?current.fromDate:'');d.setDate(d.getDate()+parseInt(chip.getAttribute('data-move-days'),10));chip.classList.toggle('is-selected',toISO(d)===dateInput.value)})}
function open(btn){current={stopId:parseInt(btn.getAttribute('data-move-stop'),10),fromDate:btn.getAttribute('data-move-from')||'',card:btn.closest('.mw-mc-card')};var label=btn.getAttribute('data-move-label')||'This stop';subEl.textContent=label+(current.fromDate?' — currently '+prettyDate(current.fromDate):'');busy=!1;resetWarning();setDate('');refreshConfirm();sheet.hidden=!1}
function close(){sheet.hidden=!0;current=null}
function submit(){if(!current||busy||!dateInput.value)return;busy=!0;confirmBtn.disabled=!0;confirmBtn.textContent='Moving…';var newDate=dateInput.value;var csrf=(window.MW_SCHEDULE_STATE&&MW_SCHEDULE_STATE.csrf)||window.MW_CSRF_TOKEN||window.MW_CSRF||'';fetch('/crm/api/reschedule-stop.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({stop_id:current.stopId,new_date:newDate,append_to_end:!0,force:force,csrf_token:csrf})}).then(function(r){return r.json()}).then(function(d){busy=!1;if(d&&d.warning){force=!0;warnEl.textContent=d.message||'That day is over capacity.';warnEl.hidden=!1;confirmBtn.textContent='Move anyway';confirmBtn.disabled=!1;return}
if(d&&d.success){var card=current.card;close();toast('Moved to '+prettyDate(newDate));if(card){card.classList.add('mw-mc-card-removing');setTimeout(function(){card.remove()},350)}
return}
confirmBtn.textContent=force?'Move anyway':'Move';refreshConfirm();toast((d&&d.error)||'Could not move this stop. Please try again.','error')}).catch(function(){busy=!1;confirmBtn.textContent=force?'Move anyway':'Move';refreshConfirm();toast('Network error — the stop was not moved.','error')})}
document.addEventListener('click',function(e){var btn=e.target.closest?e.target.closest('.mw-mc-footer-btn-move'):null;if(!btn)return;e.preventDefault();e.stopPropagation();open(btn)},!0);sheet.addEventListener('click',function(e){if(e.target.closest('[data-move-close]')){close();return}
var chip=e.target.closest('.mw-move-chip');if(chip&&current){var d=parseISO(current.fromDate);d.setDate(d.getDate()+parseInt(chip.getAttribute('data-move-days'),10));setDate(toISO(d))}});dateInput.addEventListener('change',function(){resetWarning();refreshConfirm()});confirmBtn.addEventListener('click',submit)})()